import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as r,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse(`{"title":"Qingyan / Z.ai chat","description":"Audience: frontend engineers using Zhipu's assistant in a browser or the official app. No repo required.","frontmatter":{"title":"Qingyan / Z.ai chat","description":"Audience: frontend engineers using Zhipu's assistant in a browser or the official app. No repo required.","domain":"product","tags":["coding-agent"],"role":"tutorial"},"headers":[],"relativePath":"products/zhipu-chat/zhipu-chat.md","filePath":"products/zhipu-chat/zhipu-chat.md","lastUpdated":1787107158000}`),o={name:"products/zhipu-chat/zhipu-chat.md"};function i(s,t,l,h,d,c){return r(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="qingyan-z-ai-chat" tabindex="-1">Qingyan / Z.ai chat <a class="header-anchor" href="#qingyan-z-ai-chat" aria-label="Permalink to &quot;Qingyan / Z.ai chat&quot;">​</a></h1><blockquote><p>This page is a product map from official product pages, the paid-service agreement, store listings, and model posts. Claude.ai analog.</p><p>It is <strong>not</strong> GLM Coding Plan and not ZCode. The coding subscription is one row on the <a href="./">learning map</a>.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> frontend engineers. You need a browser or the Qingyan app.</p><p><strong>Goals:</strong> say what the two official chat doors are, what they claim to do, and where accounts / billing stop.</p><p><strong>Non-goals:</strong> Coding Plan install, API SDKs, invented daily caps / token limits / current membership prices, model internals (see <a href="/tech/fundamentals/LLM.html">Learn LLM</a>).</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>You can open <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a> or <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></li><li>China surface: whatever sign-in Qingyan shows (phone / WeChat, etc.). International surface: whatever Z.ai shows</li><li>No git checkout. No API key</li></ul><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><ul><li>Pick Qingyan vs Z.ai</li><li>Send the first message and recognize official chips</li><li>Know which account holds membership, and why open-platform credit is not Qingyan membership</li></ul><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>One chat job, two official doors. Official &quot;try it online&quot; wording (<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 research post</a>):</p><table tabindex="0"><thead><tr><th>Door</th><th>Official label</th><th>URL</th></tr></thead><tbody><tr><td>China</td><td>Qingyan app / web</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td></tr><tr><td>International</td><td>Z.ai</td><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td></tr></tbody></table><p>Clients (only what official pages name):</p><table tabindex="0"><thead><tr><th>Client</th><th>Source</th></tr></thead><tbody><tr><td>Web</td><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>, <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td></tr><tr><td>Official app</td><td><a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a>; App Store <a href="https://apps.apple.com/cn/app/id6450893458" target="_blank" rel="noreferrer">Qingyan</a></td></tr><tr><td>Browser extension</td><td>Chrome Web Store &quot;智谱清言：ChatGLM &amp; AutoGLM&quot;</td></tr></tbody></table><p>There is <strong>no</strong> official &quot;install Qingyan as a repo CLI&quot; path on these pages. Code in the thread is still chat, not a checkout agent.</p><h2 id="qingyan-open-and-talk" tabindex="-1">Qingyan: open and talk <a class="header-anchor" href="#qingyan-open-and-talk" aria-label="Permalink to &quot;Qingyan: open and talk&quot;">​</a></h2><ol><li>Open <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a>.</li><li>Sign in. The paid-service agreement scopes the service to the <strong>chatglm.cn website and the Qingyan app</strong> (<a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">agreement</a> §1.5).</li><li>Ask in the box. The footer points at the <a href="https://chatglm.cn/agreement" target="_blank" rel="noreferrer">user agreement</a> and <a href="https://chatglm.cn/privacypolicy" target="_blank" rel="noreferrer">privacy policy</a>.</li></ol><p>Chips visible on the homepage on 2026-08-19:</p><table tabindex="0"><thead><tr><th>Chip</th><th>What the official page actually shows</th></tr></thead><tbody><tr><td><strong>Agent</strong></td><td>Homepage positioning is an Agent that delivers results</td></tr><tr><td><strong>研究报告</strong> (research report)</td><td>Homepage entry</td></tr><tr><td><strong>PPT制作</strong> (slides)</td><td>Homepage entry</td></tr><tr><td><strong>数据分析</strong> (data analysis)</td><td>Homepage entry</td></tr><tr><td><strong>GLM-5.2 / GLM-5.2快速</strong></td><td>Model names on the page; trust what your account can actually select</td></tr></tbody></table><p>The download page adds (<a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a>): chat, writing, programming, understanding images and documents; &quot;chat, or call tools for complex tasks.&quot;</p><p>Paid-agreement <strong>kinds</strong> of benefits (§1.6, §4.1 — not quota numbers):</p><ul><li>Model-related benefits</li><li>Agent benefits</li><li>Qingying video generation</li><li>Video calls</li><li>Larger cloud knowledge-base space</li><li>More AI image-generation features</li></ul><p><strong>Counts, credits, and whether the SKU is still called VIP/SVIP live on the in-product membership page.</strong> The agreement says Zhipu may change benefits and prices; read the live service page.</p><p>The App Store listing also groups Q&amp;A, writing, study, workplace, programming, and role-play. That is store copy, not a command list.</p><h3 id="browser-extension" tabindex="-1">Browser extension <a class="header-anchor" href="#browser-extension" aria-label="Permalink to &quot;Browser extension&quot;">​</a></h3><p>Official name: <strong>智谱清言：ChatGLM &amp; AutoGLM</strong> (Chrome Web Store, publisher zhipuextension). Store copy: sidebar Q&amp;A, page summary, page chat, selection explain/summarize/translate, writing helper, checked-text summary, on-site advanced search. Plugin policy: <a href="https://chatglm.cn/advanced-authpolicy" target="_blank" rel="noreferrer">chatglm.cn/advanced-authpolicy</a>.</p><h2 id="z-ai-international-chat" tabindex="-1">Z.ai: international chat <a class="header-anchor" href="#z-ai-international-chat" aria-label="Permalink to &quot;Z.ai: international chat&quot;">​</a></h2><ol><li>Open <a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a> or <a href="https://z.ai" target="_blank" rel="noreferrer">z.ai</a> (top nav <strong>Chat</strong>).</li><li>Sign in as the page asks. The z.ai top nav also has <strong>Chat / API / Coding Plan / Contact / Docs</strong> (<a href="https://z.ai/company" target="_blank" rel="noreferrer">z.ai/company</a>). <strong>Chat</strong> is this page. <strong>Coding Plan</strong> and <strong>Docs</strong> are not the Qingyan tutorial.</li></ol><p>Official description:</p><blockquote><p>Meet Z.ai, the AI assistant powered by GLM-5.2. Build websites, write code, handle long-horizon tasks, and get instant answers.</p></blockquote><p>Chips visible on 2026-08-19: <strong>Magic Design</strong>, <strong>Full-Stack</strong>, <strong>Write Code</strong>.</p><p>Official blog lines that survive a source check:</p><ul><li><a href="https://z.ai/blog/glm-4.5" target="_blank" rel="noreferrer">glm-4.5</a>: pick the model on Z.ai to chat; the platform supports artifacts, presentation slides, and full-stack development.</li><li><a href="https://z.ai/blog/glm-5.2" target="_blank" rel="noreferrer">glm-5.2</a>: &quot;Chat with GLM-5.2 on Z.ai&quot;. The same post puts Coding Plan / ZCode on a different path.</li></ul><p>Legal text: <a href="https://docs.z.ai/legal-agreement/terms-of-use" target="_blank" rel="noreferrer">Terms of Use</a> (JINGSHENG HENGXING TECHNOLOGY PTE.LTD). That document covers the platform / API. <strong>Do not</strong> read China Qingyan membership rules out of it.</p><h2 id="accounts-and-paid-features-agreement-text-only" tabindex="-1">Accounts and paid features (agreement text only) <a class="header-anchor" href="#accounts-and-paid-features-agreement-text-only" aria-label="Permalink to &quot;Accounts and paid features (agreement text only)&quot;">​</a></h2><p>Traps that matter, from the Qingyan paid-service agreement (effective 2026-05-21):</p><table tabindex="0"><thead><tr><th>Rule</th><th>Official point</th></tr></thead><tbody><tr><td>Benefits follow the account</td><td>If you have several Qingyan accounts, benefits go to the <strong>account you were signed into when you paid</strong>. Records do <strong>not</strong> move across accounts (§3.1, §3.2.2)</td></tr><tr><td>Not the same as the open platform</td><td>Qingyan membership and other Zhipu paid products (&quot;including but not limited to the Zhipu AI open platform&quot;) are <strong>independent</strong>. Overlap can stack; <strong>no refund</strong> for the overlap (§4.4)</td></tr><tr><td>Price is on the page</td><td>Fees, discounts, and payment methods can change; trust the service page (§4.7)</td></tr><tr><td>Default: no refund</td><td>Paid services are not returnable / cashable. Duplicate charges or official technical failure: support appeal (§4.5, §4.8.1)</td></tr><tr><td>Devices differ</td><td>App version, device, and OS can change which benefits you actually see (§4.6)</td></tr></tbody></table><p>The App Store has listed IAPs (auto-renew month, month card, Qingying agent, etc.). <strong>SKUs move.</strong> Do not treat one day&#39;s screenshot as the price list. Check the <a href="https://apps.apple.com/cn/app/id6450893458" target="_blank" rel="noreferrer">App Store page</a> or the in-product membership page.</p><p><strong>Do not assume</strong> Qingyan membership = Z.ai login = Coding Plan quota. Official pages do not say that.</p><h2 id="nearby-surfaces-do-not-mix-them" tabindex="-1">Nearby surfaces (do not mix them) <a class="header-anchor" href="#nearby-surfaces-do-not-mix-them" aria-label="Permalink to &quot;Nearby surfaces (do not mix them)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Surface</th><th>What it is</th><th>Where</th></tr></thead><tbody><tr><td><strong>Qingyan / Z.ai chat</strong></td><td>This page</td><td>chatglm.cn / chat.z.ai</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>Subscription for coding tools</td><td><a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a> — no install steps here</td></tr><tr><td><strong>ZCode</strong></td><td>Official coding tool</td><td><a href="https://zcode.z.ai/cn" target="_blank" rel="noreferrer">zcode.z.ai/cn</a></td></tr><tr><td><strong>AutoGLM / AutoClaw</strong></td><td>Report assistant / local client</td><td><a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a></td></tr><tr><td><strong>API</strong></td><td>Model HTTP APIs</td><td><a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a>, <a href="https://docs.bigmodel.cn" target="_blank" rel="noreferrer">docs.bigmodel.cn</a></td></tr></tbody></table><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Opening <a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a> or <a href="https://bigmodel.cn/glm-coding" target="_blank" rel="noreferrer">bigmodel.cn/glm-coding</a> and thinking you configured Qingyan web.</li><li>Buying on account A, signing into the web as B, then assuming the subscription vanished. The agreement says benefits do not migrate.</li><li>Treating open-platform / Coding Plan balance as Qingyan turns. The agreement says the paid products are independent.</li><li>Treating HTML or a script in the thread as a commit in your repo.</li><li>Copying third-party &quot;50 turns / day&quot; or a blog RMB price as official spec.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td>Qingyan product</td></tr><tr><td><a href="https://chatglm.cn/download" target="_blank" rel="noreferrer">chatglm.cn/download</a></td><td>App / client entry</td></tr><tr><td><a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">Paid-service agreement</a></td><td>Membership, credits, account rules</td></tr><tr><td><a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a></td><td>Z.ai chat</td></tr><tr><td><a href="https://z.ai" target="_blank" rel="noreferrer">z.ai</a></td><td>International top nav (Chat / API / Coding Plan)</td></tr><tr><td><a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn/zh</a></td><td>First-party product rail</td></tr><tr><td><a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">GLM-5.2 research post</a></td><td>Official pair of &quot;try it online&quot; URLs</td></tr><tr><td><a href="https://docs.z.ai" target="_blank" rel="noreferrer">docs.z.ai</a></td><td>API, not a Qingyan how-to</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./">Learning map</a></li><li><a href="./zhipu-chat-cheatsheet.html">Cheatsheet</a></li><li><a href="./zhipu-chat-glossary.html">Glossary</a></li></ul>',48)])])}const b=e(o,[["render",i]]);export{m as __pageData,b as default};
